/* @autogenerated */
import { signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { Observable, of, Subject } from 'rxjs';
import { AppStateService } from '@shared/context/state/app-state.service';
import { NavItem } from '../../../workspace/workspace.model';
import { WorkspaceStateService } from '../../../workspace/workspace-state.service';
import { RouteAccessService } from '../../menu/route-accessible.service';
import { NavSectionComponent } from './nav-section.component';

describe('NavSectionComponent', () => {
  let nav: ReturnType<typeof signal<NavItem[]>>;
  let contexts: ReturnType<typeof signal<Record<string, { value: unknown }>>>;
  let guards: Record<string, Observable<boolean>>;

  const create = () => {
    TestBed.configureTestingModule({
      imports: [NavSectionComponent],
      providers: [
        {
          provide: WorkspaceStateService,
          useValue: {
            nav,
            link: (route: string) => ['/', 'es', 'acme', route],
            url: (route: string) => `es/acme/${route}`,
          },
        },
        {
          provide: AppStateService,
          useValue: {
            contexts,
            language: signal('es'),
            tenant: signal('acme'),
            user: () => signal({ authenticated: true }),
          },
        },
        { provide: RouteAccessService, useValue: { checkRouteGuards: (url: string) => guards[url] ?? of(true) } },
      ],
    });
    TestBed.overrideComponent(NavSectionComponent, { set: { template: '', imports: [] } });
    const fixture = TestBed.createComponent(NavSectionComponent);
    fixture.detectChanges();
    return { fixture, section: fixture.componentInstance };
  };

  const labels = (section: NavSectionComponent) =>
    section.groups().map((group) => [group.label, group.links.map((link) => link.label)]);

  beforeEach(() => {
    nav = signal<NavItem[]>([
      { label: 'Dashboard', route: 'dashboard' },
      {
        label: 'Access',
        icon: 'folder',
        children: [
          { label: 'Clients', route: 'clients' },
          { label: 'Roles', route: 'roles', requires: ['tenant'] },
          { label: 'Nested', children: [{ label: 'Deep', route: 'deep' }] },
        ],
      },
      { label: 'Admin', requires: ['tenant'], children: [{ label: 'Users', route: 'users' }] },
    ]);
    contexts = signal({});
    guards = {};
  });

  afterEach(() => TestBed.resetTestingModule());

  it('groups the menu entries, with the loose ones first and the nested ones in their top group', () => {
    const { section } = create();

    expect(labels(section)).toEqual([
      [undefined, ['Dashboard']],
      ['Access', ['Clients', 'Deep']],
    ]);
    expect(section.groups()[1].links[0].link).toEqual(['/', 'es', 'acme', 'clients']);
  });

  it('shows what the selectors allow, as the menu does', () => {
    contexts.set({ tenant: { value: 't1' } });
    const { section } = create();

    expect(labels(section)).toEqual([
      [undefined, ['Dashboard']],
      ['Access', ['Clients', 'Roles', 'Deep']],
      ['Admin', ['Users']],
    ]);
  });

  it('hides what the guards would not open, and empty groups with it', () => {
    guards['es/acme/dashboard'] = of(false);
    const pending = new Subject<boolean>();
    guards['es/acme/deep'] = pending;
    const { section } = create();

    expect(labels(section)).toEqual([['Access', ['Clients']]]);

    pending.next(true);
    expect(labels(section)).toEqual([['Access', ['Clients', 'Deep']]]);
  });
});
